namespace ghidra.util.database.annotproc;





/**
 * An enum to represent different levels of access specifiers (private, package-private, protected,
 * public) with corresponding access levels
 */
public class AccessSpec
{	public static readonly AccessSpec PRIVATE = new(0);
	public static readonly AccessSpec PACKAGE = new(1);
	public static readonly AccessSpec PROTECTED = new(2);
	public static readonly AccessSpec PUBLIC = new(3);


	private int level;

	private AccessSpec(int level) {
		this.level = level;
	}

	/**
	 * Check if the second permits the same or more access than the first
	 * 
	 * @param first the first
	 * @param second the second
	 * @return true if the second is the same or more permissive
	 */
	public static bool isSameOrMorePermissive(AccessSpec first, AccessSpec second) {
		// TODO: I'm not sure protected actually includes package...
		// It might be more diamond shaped
		return first.level <= second.level;
	}

	/**
	 * Get the access specifier derived from the given modifiers
	 * 
	 * @param modifiers the element's modifiers
	 * @return the elements access specification
	 */
	public static AccessSpec get(Set<Modifier> modifiers) {
		if (modifiers.contains(Modifier.PRIVATE)) {
			return PRIVATE;
		}
		if (modifiers.contains(Modifier.PROTECTED)) {
			return PROTECTED;
		}
		if (modifiers.contains(Modifier.PUBLIC)) {
			return PUBLIC;
		}
		return PACKAGE;
	}
}
